window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[288]={"id":"288","numero":288,"titre":"Pathologie hémorroïdaire","objectifs":[{"id":"288-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des hémorroïdes","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">hémorroïdes</span> sont des <span class=\"kw-def\">structures anatomiques vasculaires de l'anus, normalement présentes chez l'individu sain</span> : ce sont des structures <strong>physiologiques</strong>, et non une maladie en soi.</p>\n\n      <h5>Composition d'une hémorroïde</h5>\n      <ul>\n        <li><span class=\"kw-imagerie\">Lacs veineux</span>.</li>\n        <li><span class=\"kw-imagerie\">Petites artérioles sous-muqueuses</span>.</li>\n        <li><span class=\"kw-imagerie\">Intense réseau anastomotique</span> = véritable <span class=\"kw-def\">shunt artério-veineux</span>.</li>\n        <li><span class=\"kw-imagerie\">Tissu de soutien</span> : fibres musculaires lisses et tissu collagène, qui ancrent la structure.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ La <span class=\"kw-clinique\">laxité du matériel d'ancrage avec le vieillissement</span> peut conduire à une <strong>procidence / saillie</strong> des hémorroïdes — point de départ de la maladie hémorroïdaire.</div>\n\n      <h5>Deux groupes hémorroïdaires</h5>\n      <ul>\n        <li><strong>Plexus interne</strong> : <span class=\"kw-imagerie\">sus-pectinéal</span>, intra-canalaire (détaillé à l'objectif « Savoir distinguer <span class=\"kw-clinique\">les</span> hémorroïdes externes et internes »).</li>\n        <li><strong>Plexus externe</strong> : <span class=\"kw-imagerie\">sous-pectinéal</span>, au niveau de la marge anale.</li>\n      </ul>","frequence":0},{"id":"288-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence de la pathologie hémorroïdaire","contenu":"<p>La pathologie hémorroïdaire est l'<span class=\"kw-def\">affection la plus fréquente en proctologie</span>.</p>\n\n      <h5>Fréquence</h5>\n      <ul>\n        <li>Environ <span class=\"kw-chiffre\">1/3 de la population</span> a eu au moins un symptôme hémorroïdaire au cours de l'année écoulée (et <span class=\"kw-chiffre\">1/3 d'entre eux</span> consultent).</li>\n        <li>Jusqu'à <span class=\"kw-chiffre\">80 % de la population générale</span> serait concernée au moins une fois dans sa vie.</li>\n      </ul>\n\n      <h5><span class=\"kw-def\">Terrain</span></h5>\n      <ul>\n        <li>Peut s'observer à <span class=\"kw-clinique\">tout âge</span>.</li>\n        <li><span class=\"kw-clinique\">Sans prédisposition féminine ni masculine</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Maladie bénigne, mais vigilance carcinologique.</strong> La <span class=\"kw-def\">maladie hémorroïdaire</span> ne <span class=\"kw-alerte\">menace</span> pas le <span class=\"kw-alerte\">pronostic vital</span> et <span class=\"kw-def\">ne dégénère pas</span>. En revanche, <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">saignements hémorroïdaires</span> peuvent <span class=\"kw-alerte\">gêner le dépistage du cancer colorectal</span> : un <span class=\"kw-alerte\">saignement survenant à l'occasion d'une défécation</span> est un <span class=\"kw-alerte\">signe d'alarme</span> qui impose une <span class=\"kw-imagerie\">exploration colorectale</span> (attitude à nuancer selon le <span class=\"kw-def\">terrain</span> et le contexte). Discriminant : le saignement hémorroïdaire survient classiquement <span class=\"kw-clinique\">à la fin de la selle, non mélangé aux selles</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum</em></p>","frequence":0},{"id":"288-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des hémorroïdes","contenu":"<p>La <span class=\"kw-def\">maladie hémorroïdaire</span> représente l'ensemble des plaintes en lien avec <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">modifications du tissu hémorroïdaire</span>. On distingue :</p>\n      <ul>\n        <li><span class=\"kw-def\">Crise</span> : plaintes de <span class=\"kw-clinique\">courte durée comportant une composante douloureuse</span>.</li>\n        <li><span class=\"kw-def\">Maladie chronique</span> : <span class=\"kw-clinique\">signes réguliers</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Pas de corrélation anatomo-clinique</strong> : de petites hémorroïdes peuvent être symptomatiques et de grosses hémorroïdes asymptomatiques (même si <span class=\"kw-clinique\">les</span> symptômes s'accompagnent habituellement d'une modification morphologique).</div>\n\n      <h5><span class=\"kw-clinique\">Les</span> deux théories physiopathologiques</h5>\n      <table >\n        <thead>\n          <tr><th>Théorie</th><th>Principe et conséquences</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Théorie mécanique</span></td>\n            <td>\n              <strong>Mécanisme :</strong> <span class=\"kw-alerte\">fragilisation du tissu de soutien</span> / matériel d'ancrage des hémorroïdes internes.<br>\n              <strong><span class=\"kw-def\">Facteurs de risque</span> évoqués :</strong> <span class=\"kw-clinique\">accouchement</span> ; <span class=\"kw-clinique\">long temps passé à la selle</span> ; <span class=\"kw-clinique\">efforts de poussée</span> (<span class=\"kw-clinique\">dyschésie</span>) ; <span class=\"kw-clinique\">selles dures</span>.<br>\n              <strong>Conséquence thérapeutique :</strong> la prise en charge vise à renforcer / repositionner le tissu hémorroïdaire (traitements instrumentaux, certains traitements chirurgicaux).\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Théorie vasculaire</span></td>\n            <td>\n              <strong>Principe :</strong> la maladie s'apparente à une <span class=\"kw-clinique\">insuffisance veineuse</span> — argumentée par l'<span class=\"kw-clinique\">augmentation de taille du tissu en fin de grossesse</span> et l'efficacité à court terme des <span class=\"kw-ttt\">veinotoniques</span>.<br>\n              <strong>Limites :</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">hémorroïdes ne sont pas des veines</span> (pas de valvules conniventes) ; les <span class=\"kw-bio\">saignements rouges de la crise ne sont pas veineux</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"288-4","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir distinguer les hémorroïdes externes et internes","contenu":"<img src=\"../assets/images/288/anatomie-canal-anal.png\" alt=\"Schéma anatomique du canal anal : sphincters interne et externe, hémorroïdes internes (sus-pectinéales) et externes (sous-pectinéales), ligne pectinée, ligament de Parks\" style=\"max-width:100%;height:auto;border-radius:8px;margin:.5rem 0;\">\n\n      <p>Le repère anatomique central est la <span class=\"kw-imagerie\">ligne pectinée</span> : zone de transition entre deux épithéliums, située au milieu du canal anal. Le <strong>sphincter interne se termine en regard de la ligne pectinée</strong>.</p>\n\n      <h5>Plexus externe <span class=\"kw-bio\">vs</span> plexus interne</h5>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Plexus externe</th><th>Plexus interne</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Localisation</strong></td>\n            <td>Péri-anal, immédiatement sous-cutané, dans <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">plis radiés de l'anus</span>.</td>\n            <td>Intra-canalaire, en <span class=\"kw-imagerie\">sus-pectinéal</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Histologie</span></strong></td>\n            <td><span class=\"kw-def\">Épithélium de type malpighien</span>.</td>\n            <td><span class=\"kw-def\">Épithélium de type intestinal</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Vascularisation</strong></td>\n            <td><span class=\"kw-imagerie\">Artère rectale inférieure</span>.</td>\n            <td>Branches de l'<span class=\"kw-imagerie\">artère rectale supérieure</span> — 3 paquets : <span class=\"kw-clinique\">antéro-droit, postéro-droit, latéral gauche</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Visible ?</strong></td>\n            <td>Non, sauf en cas de complication (<span class=\"kw-alerte\">thrombose externe</span>).</td>\n            <td>Uniquement en <span class=\"kw-imagerie\">anuscopie</span> (sauf <span class=\"kw-clinique\">prolapsus extériorisé</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Palpable ?</strong></td>\n            <td>Non, sauf en cas de <span class=\"kw-clinique\">thrombose hémorroïdaire externe</span>.</td>\n            <td>Non.</td>\n          </tr>\n          <tr>\n            <td><strong>Complications</strong></td>\n            <td><span class=\"kw-clinique\">Thrombose hémorroïdaire externe</span> — <strong>seule complication des hémorroïdes externes</strong>.</td>\n            <td>\n              <strong>Hémorragie :</strong> <span class=\"kw-clinique\">épistaxis anal</span> ;<br>\n              <strong>Prolapsus / procidence :</strong> <span class=\"kw-clinique\">extériorisation</span> ;<br>\n              <strong>Crise hémorroïdaire :</strong> <span class=\"kw-clinique\">crise fluxionnaire</span> ;<br>\n              <strong>Thrombose hémorroïdaire interne :</strong> <span class=\"kw-clinique\">beaucoup plus rare</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p>À noter : le plexus interne forme des <span class=\"kw-def\">renflements-coussinets (paquets hémorroïdaires)</span> et <span class=\"kw-def\">participe au tonus de repos de la partie haute du canal anal et à la continence fine</span>.</p>","frequence":0},{"id":"288-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","contenu":"<p>La <span class=\"kw-clinique\">thrombose hémorroïdaire externe</span> est la <strong>seule complication des hémorroïdes externes</strong>. Son diagnostic est <strong>clinique</strong> : l'examen clinique suffit.</p>\n\n      <h5>Facteurs déclenchants (inconstants)</h5>\n      <ul>\n        <li><span class=\"kw-clinique\">Exercice physique</span>, notamment le cyclisme.</li>\n        <li><span class=\"kw-clinique\">Contrainte mécanique</span> locale.</li>\n        <li><span class=\"kw-clinique\">Traumatisme</span> — notamment l'accouchement.</li>\n      </ul>\n\n      <h5>Douleur anale aiguë +++</h5>\n      <ul>\n        <li>Installation <span class=\"kw-clinique\">brutale</span>.</li>\n        <li>Intensité <span class=\"kw-clinique\">intense</span>.</li>\n        <li>Type : associe à divers degrés une <span class=\"kw-clinique\">sensation de cuisson, de tension et une douleur vive</span>.</li>\n        <li><span class=\"kw-clinique\">Peu ou pas rythmée par la défécation</span> — contrairement à la fissure anale.</li>\n        <li><span class=\"kw-clinique\">Rarement insomniante</span> — contrairement aux suppurations.</li>\n      </ul>\n\n      <h5>Autres symptômes</h5>\n      <ul>\n        <li>Perception d'une <span class=\"kw-clinique\">boule à l'anus</span>.</li>\n        <li>Saignements <span class=\"kw-clinique\">tardifs et inconstants</span> — notamment en cas de fistulisation spontanée, avec alors diminution de la douleur.</li>\n      </ul>\n\n      <h5>Examen clinique</h5>\n      <ul>\n        <li><span class=\"kw-imagerie\">Tuméfaction ferme mais non dure, bleutée, douloureuse à la palpation</span>, siégeant dans <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">plis radiés de l'anus</span>.</li>\n        <li>Réaction <span class=\"kw-clinique\">œdémateuse</span> souvent associée — elle peut masquer le <span class=\"kw-etio\">thrombus</span> si elle est importante (surtout en cas de <span class=\"kw-ci\">grossesse</span> ou de post-partum).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <span class=\"kw-ci\">TR et anuscopie à éviter</span> : ils sont douloureux dans cette situation, sauf en cas de doute sur un <span class=\"kw-def\">diagnostic différentiel</span> ou surajouté. <span class=\"kw-clinique\">Les</span> <strong>examens complémentaires ne sont pas nécessaires</strong> au diagnostic.</div>\n\n      <h5>Thrombose hémorroïdaire interne (beaucoup plus rare)</h5>\n      <ul>\n        <li>Douleur anale aiguë perçue comme <span class=\"kw-clinique\">« interne »</span>.</li>\n        <li>Marge anale normale ; <span class=\"kw-imagerie\">TR très douloureux percevant le thrombus</span>.</li>\n        <li><span class=\"kw-imagerie\">Anuscopie</span> : confirme le diagnostic.</li>\n      </ul>","frequence":1},{"id":"288-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques les plus fréquentes des hémorroïdes internes","contenu":"<p>Trois grandes manifestations peuvent s'associer de manière <strong>aiguë ou chronique</strong> : <span class=\"kw-clinique\">hémorragie</span>, <span class=\"kw-clinique\">prolapsus / procidence</span> et <span class=\"kw-clinique\">douleurs</span> (crise fluxionnaire, <em>détaillée à l'objectif « Connaître <span class=\"kw-clinique\">les</span> autres manifestations possibles des hémorroïdes internes »</em>).</p>\n\n      <h5>Hémorragies hémorroïdaires (« épistaxis anal »)</h5>\n      <ul>\n        <li><strong>Horaire</strong> : contemporaines de la défécation ou au décours immédiat.</li>\n        <li><strong>Couleur</strong> : <span class=\"kw-clinique\">sang rouge rutilant, vif</span> (origine artériolaire), habituellement <strong>non mélangé aux matières</strong>.</li>\n        <li><strong>Abondance</strong> : souvent faible, au goutte-à-goutte (rarement giclant), souvent <span class=\"kw-clinique\">surestimée par les patients</span>.</li>\n      </ul>\n\n      <h5>Prolapsus / procidence</h5>\n      <ul>\n        <li><strong>Mécanisme</strong> : <span class=\"kw-clinique\">laxité du tissu conjonctif sous-muqueux</span> des hémorroïdes internes — peut intéresser <span class=\"kw-clinique\">1 paquet</span> (surtout antérieur chez la femme), <span class=\"kw-clinique\">3 paquets</span>, voire être <span class=\"kw-clinique\">circonférentiel</span>.</li>\n        <li><span class=\"kw-clinique\">Extériorisation des hémorroïdes internes</span> par l'orifice anal — lors de la défécation, parfois en permanence.</li>\n        <li>Gêne mécanique : sensation de boule sortante lors des efforts de <span class=\"kw-clinique\">poussée</span>.</li>\n        <li>Dans <span class=\"kw-clinique\">les</span> formes fréquentes ou permanentes (<span class=\"kw-def\">grade</span> 3-4) : <span class=\"kw-clinique\">prurit</span>, suintement, brûlures anales.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Le <strong><span class=\"kw-clinique\">prurit</span> n'est pas considéré comme un symptôme hémorroïdaire</strong> : il ne constitue pas une indication de traitement instrumental ou chirurgical.</div>\n\n      <h5><span class=\"kw-def\">Classification</span> de Goligher (degré de procidence)</h5>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Grade</span></th><th>Degré de procidence</th><th>Réintégrable dans le canal anal ?</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> 1</strong></td>\n            <td>Hémorroïdes internes <strong>non prolabées</strong>, mais <span class=\"kw-clinique\">congestives</span> et/ou <span class=\"kw-clinique\">hémorragiques</span>.</td>\n            <td>Pas de prolapsus.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> 2</strong></td>\n            <td>Hémorroïdes internes prolabées (procidence dans la lumière de l'anuscope).</td>\n            <td>Réintègrent <strong>spontanément</strong> le canal anal.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> 3</strong></td>\n            <td>Hémorroïdes internes prolabées (extériorisées lors des poussées).</td>\n            <td>Réintègrent spontanément en dehors des poussées, ou requièrent une <span class=\"kw-imagerie\">manœuvre digitale</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> 4</strong></td>\n            <td>Hémorroïdes internes prolabées, visibles à l'extérieur de l'anus sans anuscope.</td>\n            <td><span class=\"kw-alerte\">Non réintégrables</span> — <span class=\"kw-alerte\">rupture</span> totale du l<span class=\"kw-chiffre\">iga</span>ment de Parks.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":3},{"id":"288-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître le diagnostic différentiel des hémorroïdes internes","contenu":"<p>Message clé : le <span class=\"kw-clinique\">saignement hémorroïdaire est aspécifique</span>. <span class=\"kw-alerte\">Aucun élément symptomatique</span> ne permet d'attribuer avec certitude un saignement à une origine hémorroïdaire.</p>\n\n      <h5>Quand évoquer un autre diagnostic</h5>\n      <ul>\n        <li><span class=\"kw-alerte\">Saignements indépendants de la défécation</span> : possibles, mais doivent faire évoquer un autre diagnostic.</li>\n        <li><span class=\"kw-alerte\">Saignements colorant les selles</span> : doivent également faire évoquer une autre cause — notamment un <span class=\"kw-etio\">cancer colorectal</span> ou une <span class=\"kw-etio\">MICI</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">🚩 Un <span class=\"kw-alerte\">saignement survenant à l'occasion d'une défécation</span> est un signe d'alarme imposant une <span class=\"kw-imagerie\">exploration colorectale</span> (attitude à nuancer selon le <span class=\"kw-def\">terrain</span> et le contexte clinique). Devant des <span class=\"kw-clinique\">rectorragies</span>, on ne se contente jamais d'attribuer le saignement aux hémorroïdes : il faut <span class=\"kw-alerte\">éliminer une cause organique</span>.</div>\n\n      <p>⚠️ La fiche source reste volontairement succincte sur une liste exhaustive de diagnostics différentiels des hémorroïdes internes : le point retenu est le <span class=\"kw-clinique\">caractère aspécifique du saignement</span> et la <span class=\"kw-alerte\">nécessité d'éliminer une cause organique</span>.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum · 282 — <span class=\"kw-etio\">MICI</span></em></p>","frequence":2},{"id":"288-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître le diagnostic différentiel de la thrombose hémorroïdaire externe","contenu":"<p>Le <span class=\"kw-def\">diagnostic différentiel</span> de la thrombose hémorroïdaire externe regroupe <span class=\"kw-clinique\">les</span> <strong>autres causes de douleur anale aiguë</strong>.</p>\n\n      <!-- L'image Untitled 1.png (capture de tableau) NE doit PAS être collée : son contenu est retranscrit ci-dessous. -->\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Type de douleur</th><th>Rythme</th><th>Durée</th><th>Signes associés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Crise hémorroïdaire</strong></td>\n            <td>Cuisson.</td>\n            <td>Per- et post-défécatoire, <strong>peu durable</strong>.</td>\n            <td><span class=\"kw-chiffre\">24-72 h</span>.</td>\n            <td><span class=\"kw-clinique\">Œdème</span>, procidence, saignement.</td>\n          </tr>\n          <tr>\n            <td><strong>Thrombose hémorroïdaire</strong></td>\n            <td>Douleur intense « exquise ».</td>\n            <td>Non rythmée par la selle.</td>\n            <td>Heures à jours.</td>\n            <td><span class=\"kw-clinique\">Tuméfaction</span> anale douloureuse bleutée bien limitée.</td>\n          </tr>\n          <tr>\n            <td><strong>Fissure anale</strong></td>\n            <td>Brûlure.</td>\n            <td>Per- et post-défécatoire <strong>durable</strong> (persiste plusieurs heures).</td>\n            <td>Semaines.</td>\n            <td>Saignement.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Abcès</span></strong></td>\n            <td>Tension, douleur pongitive.</td>\n            <td>\n              <strong>Positionnel de <span class=\"kw-def\">contact</span> :</strong> augmentée au toucher / appui ;<br>\n              <strong><span class=\"kw-etio\">Inflammatoire</span> :</strong> insomniante.\n            </td>\n            <td>Récente (quelques heures), continue.</td>\n            <td><span class=\"kw-clinique\">Tuméfaction</span> périanale mal limitée, rouge mais non bleutée, halo érythémateux, <span class=\"kw-clinique\">dysurie</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Fécalome / Cancer</strong></td>\n            <td>Épreintes.</td>\n            <td>Avant la selle (douleurs expulsives).</td>\n            <td>Jours.</td>\n            <td>Suintements, incontinence.</td>\n          </tr>\n          <tr>\n            <td><strong>Herpès</strong></td>\n            <td>Brûlures intenses.</td>\n            <td>Péri-anales en quadrant.</td>\n            <td>Jours.</td>\n            <td>Lésions ulcérées et érosives périanales, <span class=\"kw-clinique\">dysurie</span>, hyperesthésie régionale.</td>\n          </tr>\n          <tr>\n            <td><strong>Proctalgie fugace</strong></td>\n            <td>Crampe intense.</td>\n            <td>Début brutal, sans facteur déclenchant franc.</td>\n            <td>Minutes (parfois nocturne).</td>\n            <td>Aucun.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Focus — la fissure anale (<span class=\"kw-def\">diagnostic différentiel</span> principal)</h5>\n      <p>Le diagnostic est évoqué devant une <strong>triade</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Ulcération épithéliale en forme de raquette</span> à la partie basse du canal anal, <strong>postérieure dans <span class=\"kw-chiffre\">75 %</span> des cas</strong> (plus rarement antérieure ou bipolaire).</li>\n        <li><span class=\"kw-clinique\">Hypertonie du sphincter interne</span> (sphincter contracté au repos, responsable de la douleur).</li>\n        <li><span class=\"kw-clinique\">Douleur typique en 3 temps</span> : déclenchée par le passage des selles → <span class=\"kw-clinique\">rémission</span> transitoire de quelques secondes à minutes → reprise douloureuse plus ou moins prolongée (peut durer quelques heures).</li>\n      </ul>\n      <p>Devant une forme atypique (fissure indolore, latérale, absence de contracture sphinctérienne), il faut évoquer :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Ulcération</span> de la <span class=\"kw-clinique\">maladie de Crohn</span>.</li>\n        <li><span class=\"kw-etio\">Carcinome épidermoïde de l'anus</span> (plus rarement une hémopathie maligne).</li>\n        <li><span class=\"kw-clinique\">Infection sexuellement transmissible</span> : <span class=\"kw-etio\">syphilis</span>, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">chlamydiae</span>, <span class=\"kw-etio\">herpès simplex</span>.</li>\n        <li><span class=\"kw-clinique\">Traumatisme</span> (valeur du contexte).</li>\n        <li><span class=\"kw-clinique\">Séquelle de radiothérapie</span> (valeur du contexte).</li>\n        <li><span class=\"kw-clinique\">Maladie de système</span> : <span class=\"kw-etio\">maladie de Behçet</span>, <span class=\"kw-etio\">granulomatose de Wegener</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 282 — <span class=\"kw-etio\">MICI</span></em></p>","frequence":0},{"id":"288-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les autres manifestations possibles des hémorroïdes internes","contenu":"<h5>Anémie ferriprive par saignement chronique</h5>\n      <ul>\n        <li><span class=\"kw-etio\">Anémie ferriprive</span> liée à un saignement hémorroïdaire chronique : <span class=\"kw-chiffre\">très rare</span>.</li>\n        <li>Doit faire <span class=\"kw-alerte\">éliminer les autres causes d'anémie ferriprive</span> avant de l'attribuer aux hémorroïdes.</li>\n      </ul>\n\n      <h5>Crise fluxionnaire (hémorroïdaire)</h5>\n      <ul>\n        <li>Regroupe <span class=\"kw-clinique\">toutes les douleurs causées par une hémorroïde interne, hors thrombose</span> — y compris <span class=\"kw-clinique\">sensation de chaleur et pesanteur périnéale</span>.</li>\n        <li>Diagnostic posé <span class=\"kw-alerte\">après élimination d'une pathologie alternative</span> (notamment <span class=\"kw-clinique\">fissure ou suppuration</span>).</li>\n        <li><span class=\"kw-clinique\">FR déclenchants</span> (inconstants) : <span class=\"kw-clinique\">diarrhée</span>, <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-clinique\">effort de type dyschésie</span>, excès de table (<span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">plats épicés</span>).</li>\n        <li><span class=\"kw-clinique\">Facteur aggravant</span> : <span class=\"kw-clinique\">passage à la selle</span>, <span class=\"kw-clinique\">exercice physique</span>.</li>\n        <li>Durée moyenne : <span class=\"kw-chiffre\">24-72 h</span>.</li>\n        <li><span class=\"kw-imagerie\">Examen endoscopique</span> : aspect congestif, œdémateux, parfois un semis de microthromboses.</li>\n      </ul>\n\n      <h5>Thrombose hémorroïdaire interne</h5>\n      <ul>\n        <li>Beaucoup plus rare que la thrombose hémorroïdaire externe (sémiologie décrite à l'objectif « Connaître <span class=\"kw-clinique\">les</span> modalités du diagnostic d'une thrombose hémorroïdaire »).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum · 213 — Anémie</em></p>","frequence":2},{"id":"288-10","rang":"A","rubrique":"Contenu multimédia","titre":"Photographies d’hémorroïdes externes et hémorroïdes internes prolabées","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune photographie d'hémorroïdes externes ou internes prolabées n'est présente dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>288-pathologie-hemorroidaire/</code>. Kevin ajoutera l'iconographie clinique (Collège HGE, atlas de proctologie) lors d'un B-FIX ultérieur.\n      </div>\n      <!-- TODO Kevin : photos cliniques externes / internes prolabées à fournir -->","frequence":0,"liens":[{"href":"https://radiologyassistant.nl/abdomen/rectum","label":"Radiology Assistant — Rectum"},{"href":"https://radiopaedia.org/articles/rectum","label":"Radiopaedia : Rectum"},{"href":"https://radiopaedia.org/cases/rectal-anatomy-illustrations?lang=gb","label":"Radiopaedia : Rectal anatomy illustrations"}]},{"id":"288-11","rang":"A","rubrique":"Contenu multimédia","titre":"Photographies de thrombose hémorroïdaire","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune photographie de thrombose hémorroïdaire n'est présente dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>288-pathologie-hemorroidaire/</code>. La sémiologie clinique attendue est décrite à l'objectif « Connaître les modalités du diagnostic d'une thrombose hémorroïdaire » (<span class=\"kw-clinique\">tuméfaction</span> ferme bleutée des plis radiés). Kevin ajoutera la photographie lors d'un B-FIX ultérieur.\n      </div>\n      <!-- TODO Kevin : photo clinique de thrombose hémorroïdaire externe à fournir -->","frequence":0},{"id":"288-12","rang":"B","rubrique":"Etiologie","titre":"Connaître les principaux facteurs favorisant la pathologie hémorroïdaire","contenu":"<h5>Facteurs favorisants principaux</h5>\n      <ul>\n        <li><span class=\"kw-clinique\">Troubles du transit intestinal</span>, en particulier la <span class=\"kw-clinique\">dyschésie</span>.</li>\n        <li><span class=\"kw-clinique\">3ᵉ trimestre de grossesse</span>.</li>\n        <li><span class=\"kw-clinique\">Accouchement</span>.</li>\n        <li><span class=\"kw-clinique\">Post-partum immédiat</span>.</li>\n      </ul>\n\n      <h5>Facteurs discutés (non établis)</h5>\n      <ul>\n        <li><span class=\"kw-clinique\">Antécédents familiaux</span>.</li>\n        <li><span class=\"kw-clinique\">Alimentation épicée</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 283 — <span class=\"kw-clinique\">Constipation</span></em></p>","frequence":0},{"id":"288-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","contenu":"<h5><span class=\"kw-ttt\">Règles hygiéno-diététiques</span> (traitement non <span class=\"kw-etio\">médicamenteux</span>)</h5>\n      <ul>\n        <li>Lutter contre la <span class=\"kw-clinique\">constipation chronique</span> ++ : limite l'installation de la maladie, résout <span class=\"kw-clinique\">les</span> symptômes et prévient récidives et complications.</li>\n        <li>Alimentation riche en <strong>fibres solubles</strong> : graines de lin, graines de chia, psyllium blond.</li>\n        <li><span class=\"kw-ttt\">Laxatifs doux</span> en cas de <span class=\"kw-clinique\">constipation</span> : <strong>mucilage</strong> ou <strong>macrogol</strong>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">❌ <span class=\"kw-clinique\">Les</span> <strong>régimes d'exclusion alimentaire n'ont pas d'efficacité</strong>.</div>\n\n      <h5>Traitement <span class=\"kw-etio\">médicamenteux</span></h5>\n      <p>Utilisation <strong>ponctuelle</strong> lors des épisodes douloureux, en <strong>cure courte</strong> — ce n'est pas le traitement des formes chroniques.</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Antalgiques</span> et <span class=\"kw-ttt\">AINS</span>.</li>\n        <li><span class=\"kw-ttt\">Veinotonique</span> (diosmine) : efficacité démontrée, diminue l'intensité et la durée des symptômes.</li>\n        <li><span class=\"kw-ttt\">Topiques locaux</span> : <span class=\"kw-ttt\">émollients</span>, analgésiques, anti-inflammatoires, anti-<span class=\"kw-clinique\">œdème</span>, favorisant la cicatrisation.</li>\n      </ul>\n\n      <h5>Traitement instrumental</h5>\n      <p>Traitement de fond de la <strong>maladie hémorroïdaire interne</strong>, réalisé en consultation spécialisée à travers un anuscope, <strong>en dehors des poussées</strong>. Il est appliqué <strong>sur la muqueuse rectale au-dessus du tissu hémorroïdaire</strong> (et non sur <span class=\"kw-clinique\">les</span> hémorroïdes elles-mêmes) — la <span class=\"kw-imagerie\">muqueuse rectale est dépourvue de sensibilité thermo-algésique</span>. Ce <strong>n'est pas un traitement préventif de la thrombose</strong>.</p>\n      <table >\n        <thead>\n          <tr><th>Technique</th><th>Type</th><th>Particularité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">Ligature élastique</span></td>\n            <td><span class=\"kw-etio\">Ischémique</span></td>\n            <td><strong>Meilleur compromis bénéfice / risque</strong> ; <span class=\"kw-ci\">contre-indiquée sous anticoagulants ou double anti-agrégation</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Sclérose</span></td>\n            <td>Chimique</td>\n            <td>Injection d'un produit sclérosant <span class=\"kw-chiffre\">2 cm au-dessus de la ligne pectinée</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Photocoagulation infrarouge</span></td>\n            <td>Thermique</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Coagulation bipolaire</span></td>\n            <td>Thermique</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Cryothérapie</span></td>\n            <td>Thermique</td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Bénéfice important dans ≥ <span class=\"kw-chiffre\">3/4 des cas</span> ; efficacité décroissante avec le <span class=\"kw-def\">suivi</span> → à <strong>répéter</strong> (<span class=\"kw-chiffre\">2-4 fois</span> en moyenne, environ tous <span class=\"kw-clinique\">les</span> mois). Complications rares : <span class=\"kw-alerte\">saignement sur chute d'escarre</span> (surtout après l<span class=\"kw-chiffre\">iga</span>ture), <span class=\"kw-alerte\">infections</span> (surtout après <span class=\"kw-ttt\">sclérose</span>).</p>\n\n      <h5>Traitement chirurgical</h5>\n      <p>Acte réalisé sous <span class=\"kw-ttt\">anesthésie générale, péridurale ou locorégionale</span>.</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Hémorroïdectomie</span> (résection) : <strong>traitement de référence en efficacité</strong>, mais <strong>plus douloureuse</strong>.</li>\n        <li>Techniques de <span class=\"kw-ttt\">fixation / pexie</span> (mécanique ou thermique : radiofréquence, <span class=\"kw-ttt\">laser</span>) : plus rapides, moins douloureuses, immobilisation plus courte, mais <span class=\"kw-alerte\">risque de récidive plus important</span>.</li>\n        <li><span class=\"kw-alerte\">Séquelle fonctionnelle rare (incontinence)</span> : doit être prévenue et <strong>évaluée avant le geste</strong>.</li>\n      </ul>\n\n      <h5>Escalade thérapeutique selon le <span class=\"kw-def\">grade</span> de Goligher</h5>\n      <p>Le traitement est <strong>progressif</strong>, adapté au <span class=\"kw-def\">grade</span> de sévérité : on n'escalade qu'en cas d'échec du palier précédent.</p>\n      <table >\n        <thead>\n          <tr><th>Grade</th><th>1ʳᵉ intention</th><th>Si échec / récidive</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> I</strong></td>\n            <td><span class=\"kw-ttt\">RHD</span> + traitement médical.</td>\n            <td>Photocoagulation infrarouge ou <span class=\"kw-ttt\">sclérose</span>, puis l<span class=\"kw-chiffre\">iga</span>ture.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> II</strong></td>\n            <td><span class=\"kw-ttt\">RHD</span> + traitement médical.</td>\n            <td>Photocoagulation, <span class=\"kw-ttt\">sclérose</span> ou l<span class=\"kw-chiffre\">iga</span>ture élastique, puis hémorroïdopexie / hémorroïdectomie.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> III</strong></td>\n            <td><span class=\"kw-ttt\">RHD</span> + traitement médical.</td>\n            <td>L<span class=\"kw-chiffre\">iga</span>ture élastique, puis mucopexie / hémorroïdopexie, voire hémorroïdectomie.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> IV</strong></td>\n            <td><span class=\"kw-ttt\">Hémorroïdectomie</span> d'emblée (prolapsus irréductible).</td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">📌 Principe général : débuter par <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-ttt\">règles hygiéno-diététiques</span> + traitement médical</strong>, puis les <strong>procédés mini-invasifs</strong> (photocoagulation, l<span class=\"kw-chiffre\">iga</span>ture) en cas d'échec ; la <strong><span class=\"kw-ttt\">chirurgie</span></strong> est réservée aux formes sévères ou compliquées.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 283 — <span class=\"kw-clinique\">Constipation</span></em></p>","frequence":3},{"id":"288-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les quatre règles de préambule thérapeutique","contenu":"<p>Quatre <span class=\"kw-def\">mesures générales</span> encadrent toute prise en charge de la pathologie hémorroïdaire :</p>\n      <ol>\n        <li>Le traitement des hémorroïdes doit être <span class=\"kw-alerte\">réservé aux <span class=\"kw-clinique\">formes symptomatiques</span></span>.</li>\n        <li>C'est un <span class=\"kw-ttt\">traitement de confort</span> dans la majorité des cas.</li>\n        <li><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">traitements médicamenteux</span> sont habituellement réservés aux <span class=\"kw-clinique\">symptômes aigus</span> et proposés en <span class=\"kw-ttt\">cure courte</span>.</li>\n        <li><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">procédés instrumentaux et chirurgicaux</span> constituent le traitement de la <span class=\"kw-clinique\">maladie hémorroïdaire interne</span> (prise en charge spécialisée).</li>\n      </ol>","frequence":0},{"id":"288-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement de la thrombose hémorroïdaire externe","contenu":"<p>Le traitement de la <span class=\"kw-clinique\">thrombose hémorroïdaire externe</span> est une <span class=\"kw-alerte\">urgence antalgique</span>.</p>\n\n      <h5>Traitement médical</h5>\n      <ul>\n        <li><span class=\"kw-ttt\">AINS</span> ++.</li>\n        <li><span class=\"kw-ttt\">Antalgiques</span> de palier 1-2.</li>\n        <li><span class=\"kw-ttt\">Topiques</span> contenant un <span class=\"kw-ttt\">anesthésique local</span>.</li>\n        <li><span class=\"kw-ttt\">Veinotonique</span> (niveau de preuve faible).</li>\n        <li><span class=\"kw-ttt\">Corticoïde en cure courte</span> : alternative si <span class=\"kw-ci\">contre-indication aux AINS et au traitement chirurgical</span> (notamment en cas de forte composante œdémateuse).</li>\n      </ul>\n\n      <h5>Geste local (≠ <span class=\"kw-ttt\">chirurgie</span>)</h5>\n      <ul>\n        <li><span class=\"kw-imagerie\">Incision ou excision</span> de la zone thrombosée, réalisée en consultation — préférer l'<span class=\"kw-ttt\">excision</span> (meilleure efficacité, effet plus durable).</li>\n        <li>Indications : <span class=\"kw-clinique\">d'emblée si la thrombose est vue précocement</span>, ou en cas d'<span class=\"kw-clinique\">inefficacité du traitement médical après <span class=\"kw-chiffre\">24-48 h</span></span>.</li>\n        <li><span class=\"kw-ci\">Contre-indication</span> : thrombose <span class=\"kw-clinique\">œdémateuse</span> — risque d'<span class=\"kw-alerte\">inefficacité et d'hémorragie</span>.</li>\n      </ul>","frequence":1},{"id":"288-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications du traitement chirurgical","contenu":"<h5>Indications directes à la <span class=\"kw-ttt\">chirurgie</span></h5>\n      <ul>\n        <li><span class=\"kw-etio\">Anémie ferriprive</span> liée aux saignements.</li>\n        <li>Prolapsus hémorroïdaire <span class=\"kw-clinique\">thrombosé et hyperalgique</span>.</li>\n        <li>Thromboses hémorroïdaires externes <span class=\"kw-clinique\">récidivantes</span>.</li>\n        <li><span class=\"kw-clinique\">Pathologies proctologiques associées</span> nécessitant une intervention chirurgicale.</li>\n        <li><span class=\"kw-clinique\">Marisques hypertrophiques</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">📌 Dans l'algorithme par <span class=\"kw-def\">grade de Goligher</span>, le <span class=\"kw-chiffre\">grade IV</span> (<span class=\"kw-clinique\">prolapsus irréductible</span>) a pour traitement de référence l'<span class=\"kw-ttt\">hémorroïdectomie</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p>","frequence":0},{"id":"288-17","rang":"B","rubrique":"Suivi et / ou pronostic","titre":"Connaître l’évolution spontanée de la thrombose hémorroïdaire externe","contenu":"<h5>Évolutions spontanées possibles</h5>\n      <ul>\n        <li><span class=\"kw-clinique\">Régression lente</span> de la crise avec <span class=\"kw-clinique\">rémission anatomique complète ad integrum</span> en <span class=\"kw-chiffre\">5-15 jours</span>.</li>\n        <li><span class=\"kw-clinique\">Fistulisation à la peau</span> : se traduit par un <span class=\"kw-clinique\">saignement minime</span> et une régression / sédation des douleurs.</li>\n        <li>Formation possible d'une <span class=\"kw-clinique\">marisque</span> : <span class=\"kw-def\">repli mucocutané résiduel</span> lié à la distension cutanée par la thrombose, sans retour à une anatomie normale (<span class=\"kw-clinique\">préjudice surtout esthétique</span>, rarement une indication de traitement).</li>\n      </ul>\n\n      <h5><span class=\"kw-def\">Pronostic</span></h5>\n      <ul>\n        <li><span class=\"kw-clinique\">Évolution</span> <span class=\"kw-def\">bénigne dans tous les cas</span> : <span class=\"kw-alerte\">pas de risque embolique</span>.</li>\n        <li><span class=\"kw-alerte\">Complications suppuratives secondaires</span> exceptionnelles.</li>\n        <li><span class=\"kw-clinique\">Récidives possibles</span>, y compris sur le même site.</li>\n      </ul>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Thrombose hémorroïdaire externe <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> <span class=\"kw-ttt\">antalgique</span></span></strong></p><p>Geste local (<span class=\"kw-ttt\">excision</span> &gt; incision) <span class=\"kw-clinique\">d'emblée si thrombose vue précocement</span>, ou après <span class=\"kw-clinique\">échec du traitement médical</span> à <span class=\"kw-chiffre\">24-48 h</span> — <span class=\"kw-ci\">contre-indiqué si thrombose œdémateuse</span></p><ul><li>Douleur anale <span class=\"kw-clinique\">brutale et intense</span> ; <span class=\"kw-clinique\">tuméfaction bleutée</span> des <span class=\"kw-clinique\">plis radiés de l'anus</span></li><li>Traitement médical : <span class=\"kw-ttt\">AINS</span> ++, <span class=\"kw-ttt\">antalgiques</span> de palier 1-2, <span class=\"kw-ttt\">topiques anesthésiques</span>, <span class=\"kw-ttt\">veinotonique</span> ; <span class=\"kw-ttt\">corticoïde</span> en cure courte si <span class=\"kw-ci\">CI aux AINS</span></li></ul><p><strong>Saignement à l'occasion d'une défécation <span class=\"q\">— signe d'alarme</span></strong></p><p><span class=\"kw-imagerie\">Exploration colorectale</span> sans retard (à nuancer selon le <span class=\"kw-def\">terrain</span> et le contexte)</p><ul><li><span class=\"kw-alerte\">Saignement survenant à l'occasion d'une défécation</span> = signe d'alarme</li><li>Ne jamais imputer une <span class=\"kw-clinique\">rectorragie</span> aux hémorroïdes sans avoir éliminé une <span class=\"kw-alerte\">cause organique</span></li></ul>","hospit":"<p><strong>Ambulatoire :</strong> prise en charge en règle <span class=\"kw-clinique\">ambulatoire</span> — maladie <span class=\"kw-def\">bénigne</span>, sans <span class=\"kw-alerte\">urgence</span> vitale ni risque <span class=\"kw-etio\">embolique</span>.<br><strong>Consultation spécialisée :</strong> <span class=\"kw-ttt\">traitement instrumental</span> réalisé à travers un <span class=\"kw-imagerie\">anuscope</span>, en consultation externe de gastro-entérologie.<br><strong>Bloc opératoire :</strong> <span class=\"kw-ttt\">traitement chirurgical</span> sous <span class=\"kw-ttt\">anesthésie générale, péridurale ou locorégionale</span> (formes sévères ou compliquées).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Saignement à l'occasion d'une défécation</span> → <span class=\"kw-imagerie\">exploration colorectale</span> (éliminer un <span class=\"kw-etio\">cancer colorectal</span>)</li><li><span class=\"kw-alerte\">Saignement indépendant de la défécation</span> ou <span class=\"kw-alerte\">colorant / mélangé aux selles</span> → évoquer un <span class=\"kw-etio\">cancer colorectal</span> ou une <span class=\"kw-etio\">MICI</span></li><li><span class=\"kw-alerte\">Anémie ferriprive</span> par saignement chronique → éliminer une autre cause avant de l'attribuer aux hémorroïdes</li><li><span class=\"kw-clinique\">Rectorragie</span> : <span class=\"kw-ci\">ne jamais</span> l'imputer aux hémorroïdes sans avoir <span class=\"kw-alerte\">éliminé une cause organique</span></li><li><span class=\"kw-clinique\">Douleur anale atypique</span> (fissure indolore, latérale, sans hypertonie) → évoquer <span class=\"kw-etio\">maladie de Crohn</span>, <span class=\"kw-etio\">carcinome épidermoïde de l'anus</span>, <span class=\"kw-etio\">IST</span></li></ul>","principes":"<p><strong>4 règles de préambule :</strong> traitement <span class=\"kw-clinique\">réservé aux formes symptomatiques</span> · <span class=\"kw-ttt\">traitement de confort</span> dans la majorité des cas · <span class=\"kw-ttt\">médicaments</span> en <span class=\"kw-ttt\">cure courte</span> sur <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">symptômes aigus</span> · <span class=\"kw-ttt\">procédés instrumentaux et chirurgicaux</span> = traitement de la <span class=\"kw-def\">maladie hémorroïdaire interne</span> (PEC spécialisée). Le traitement est <span class=\"kw-clinique\">progressif, adapté au grade de Goligher</span>.</p><p><strong>Mesures générales <span class=\"q\">— 1re ligne, tous grades</span></strong></p><ul><li>Lutte contre la <span class=\"kw-clinique\">constipation chronique</span> ++ : alimentation riche en <strong>fibres solubles</strong> (lin, chia, psyllium)</li><li><span class=\"kw-ttt\">Laxatifs doux</span> si <span class=\"kw-clinique\">constipation</span> : <span class=\"kw-ttt\">mucilage</span> ou <span class=\"kw-ttt\">macrogol</span></li><li><span class=\"kw-ci\">Régimes d'exclusion alimentaire</span> inefficaces</li></ul><p><strong>Traitement <span class=\"kw-etio\">médicamenteux</span> <span class=\"q\">— <span class=\"kw-clinique\">poussée</span>, cure courte</span></strong></p><ul><li><span class=\"kw-ttt\">Antalgiques</span> et <span class=\"kw-ttt\">AINS</span> ponctuels</li><li><span class=\"kw-ttt\">Veinotonique</span> (diosmine) : diminue intensité et durée des symptômes</li><li><span class=\"kw-ttt\">Topiques locaux</span> : <span class=\"kw-ttt\">émollients</span>, analgésiques, anti-inflammatoires</li></ul><p><strong>Traitement instrumental <span class=\"q\">— maladie interne, hors <span class=\"kw-clinique\">poussée</span></span></strong></p><p>Appliqué sur la <span class=\"kw-imagerie\">muqueuse rectale au-dessus du tissu hémorroïdaire</span>, en dehors des poussées</p><ul><li><span class=\"kw-ttt\">Ligature élastique</span> : meilleur compromis bénéfice / risque — <span class=\"kw-ci\">CI sous anticoagulants ou double anti-agrégation</span></li><li><span class=\"kw-ttt\">Sclérose</span> (chimique) · <span class=\"kw-ttt\">photocoagulation infrarouge</span> · <span class=\"kw-ttt\">cryothérapie</span> (thermique)</li><li>Bénéfice dans ≥ <span class=\"kw-chiffre\">3/4 des cas</span> ; à <span class=\"kw-clinique\">répéter</span> (<span class=\"kw-chiffre\">2-4 fois</span>, environ tous <span class=\"kw-clinique\">les</span> mois)</li></ul><p><strong>Traitement chirurgical <span class=\"q\">— formes sévères / compliquées</span></strong></p><p>Réservé aux <span class=\"kw-clinique\">grades sévères</span> ou aux <span class=\"kw-alerte\">complications</span> ; prévenir et évaluer avant le geste la <span class=\"kw-alerte\">séquelle fonctionnelle (incontinence)</span></p><ul><li><span class=\"kw-ttt\">Hémorroïdectomie</span> : traitement de référence en efficacité, mais <span class=\"kw-clinique\">plus douloureuse</span></li><li><span class=\"kw-ttt\">Pexie / fixation</span> (mécanique ou thermique) : moins douloureuse mais <span class=\"kw-alerte\">récidive plus fréquente</span></li></ul>","suivi":"<p><strong>Thrombose externe :</strong> régression spontanée <span class=\"kw-clinique\">ad integrum</span> en <span class=\"kw-chiffre\">5-15 jours</span> ; possibles <span class=\"kw-clinique\">fistulisation</span> ou <span class=\"kw-clinique\">marisque</span> résiduelle (préjudice esthétique).<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-def\">bénin</span>, <span class=\"kw-alerte\">pas de risque embolique</span> ; <span class=\"kw-clinique\">récidives possibles</span>, y compris sur le même site.<br><strong>Traitement instrumental :</strong> efficacité décroissante → à <span class=\"kw-clinique\">répéter</span> ; surveiller <span class=\"kw-alerte\">saignement sur chute d'escarre</span> et <span class=\"kw-alerte\">infection</span>.<br><strong><span class=\"kw-def\">Réévaluation</span> spécialisée :</strong> devant une <span class=\"kw-clinique\">récidive</span> ou une <span class=\"kw-clinique\">forme compliquée</span> (anémie, thrombose récidivante) → discuter la <span class=\"kw-ttt\">chirurgie</span>.</p>"},"liensGlobaux":[{"href":"https://www.fmcgastro.org/texte-postu/postu-2021-paris/prise-en-charge-de-la-maladie-hemorroidaire-recommandations-europeennes/","label":"Prise en charge de la maladie hemorroidaire recommandations europeennes"},{"href":"https://fr.wikipedia.org/wiki/Rectum","label":"Wikipedia — Rectum"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Maladie hémorroïdaire interne symptomatique — Forme symptomatique confirmée (sinon abstention) — après élimination d'une cause organique de saignement","detail":"<h4>CAT — maladie hémorroïdaire interne symptomatique — Prise en charge progressive selon le <span class=\"kw-def\">grade</span> de Goligher et la réponse au traitement</h4>","branches":[{"to":"t-chir","label":"Indication chirurgicale d'emblée (grade IV irréductible, anémie ferriprive, prolapsus thrombosé hyperalgique, thromboses externes récidivantes)","color":"red"},{"to":"q-grade","label":"Pas d'indication chirurgicale directe","color":"green"}]},{"id":"t-chir","kind":"terminal","label":"Hémorroïdectomie (traitement de référence)","color":"red","detail":"<h4>Indications directes</h4><ul><li><span class=\"kw-clinique\">Grade IV</span> : prolapsus <span class=\"kw-clinique\">irréductible</span> (<span class=\"kw-alerte\">rupture</span> totale du l<span class=\"kw-chiffre\">iga</span>ment de Parks)</li><li><span class=\"kw-etio\">Anémie ferriprive</span> liée aux saignements</li><li>Prolapsus <span class=\"kw-clinique\">thrombosé et hyperalgique</span></li><li>Thromboses externes <span class=\"kw-clinique\">récidivantes</span>, <span class=\"kw-clinique\">marisques hypertrophiques</span>, pathologie proctologique associée</li></ul><h4>Geste</h4><ul><li><span class=\"kw-ttt\">Hémorroïdectomie</span> (résection) sous <span class=\"kw-ttt\">anesthésie générale, péridurale ou locorégionale</span> — référence en efficacité, mais <span class=\"kw-clinique\">plus douloureuse</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Prévenir et évaluer avant le geste la <span class=\"kw-alerte\">séquelle fonctionnelle (incontinence)</span>, rare</li></ul>"},{"id":"q-grade","kind":"decision","label":"RHD + traitement médical bien conduits ? — Mesures hygiéno-diététiques + traitement médical = 1re ligne quel que soit le grade","branches":[{"to":"t-rhd","label":"Non encore tentés / efficaces — 1re ligne","color":"green"},{"to":"q-grade2","label":"Oui — échec : escalade selon le grade de Goligher","color":"amber"}]},{"id":"t-rhd","kind":"terminal","label":"RHD + traitement médical","color":"green","detail":"<h4><span class=\"kw-ttt\">Règles hygiéno-diététiques</span></h4><ul><li>Lutte contre la <span class=\"kw-clinique\">constipation chronique</span> ++</li><li>Alimentation riche en <strong>fibres solubles</strong> (lin, chia, psyllium)</li><li><span class=\"kw-ttt\">Laxatifs doux</span> si <span class=\"kw-clinique\">constipation</span> : <span class=\"kw-ttt\">mucilage</span> ou <span class=\"kw-ttt\">macrogol</span></li></ul><h4>Traitement médical (cure courte)</h4><ul><li><span class=\"kw-ttt\">Antalgiques</span>, <span class=\"kw-ttt\">AINS</span></li><li><span class=\"kw-ttt\">Veinotonique</span> (diosmine), <span class=\"kw-ttt\">topiques locaux</span></li></ul><h4>À éviter</h4><ul><li><span class=\"kw-ci\">Régimes d'exclusion alimentaire</span> (inefficaces)</li></ul>"},{"id":"q-grade2","kind":"decision","label":"Grade de procidence (classification de Goligher) ? — I = non prolabé · II = réintègre spontanément · III = réintégration digitale / récidivant · IV = irréductible","branches":[{"to":"t-photo","label":"Grade I–II","color":"blue"},{"to":"t-ligature","label":"Grade II–III","color":"amber"},{"to":"t-pexie","label":"Grade III récidivant","color":"amber"}]},{"id":"t-photo","kind":"terminal","label":"Photocoagulation infrarouge / sclérose","color":"blue","detail":"<h4>Modalités</h4><ul><li><span class=\"kw-ttt\">Photocoagulation infrarouge</span>, <span class=\"kw-ttt\">coagulation bipolaire</span>, <span class=\"kw-ttt\">cryothérapie</span> (thermique)</li><li><span class=\"kw-ttt\">Sclérose</span> chimique : injection <span class=\"kw-chiffre\">2 cm au-dessus de la ligne pectinée</span></li></ul><h4>Conditions</h4><ul><li>Sur la <span class=\"kw-imagerie\">muqueuse rectale au-dessus du tissu hémorroïdaire</span>, en dehors des poussées ; à <span class=\"kw-clinique\">répéter</span> (<span class=\"kw-chiffre\">2-4 fois</span>)</li></ul><h4>Complications</h4><ul><li><span class=\"kw-alerte\">Saignement sur chute d'escarre</span>, <span class=\"kw-alerte\">infection</span> (surtout après <span class=\"kw-ttt\">sclérose</span>)</li></ul>"},{"id":"t-ligature","kind":"terminal","label":"Ligature élastique","color":"amber","detail":"<h4>Modalité</h4><ul><li><span class=\"kw-ttt\">Ligature élastique</span> du paquet hémorroïdaire interne — <strong>meilleur compromis bénéfice / risque</strong></li></ul><h4><span class=\"kw-ci\">Contre-indication</span></h4><ul><li><span class=\"kw-ci\">Anticoagulants</span> ou <span class=\"kw-ci\">double anti-agrégation</span></li></ul><h4>Complications</h4><ul><li><span class=\"kw-alerte\">Saignement sur chute d'escarre</span> (surtout après l<span class=\"kw-chiffre\">iga</span>ture)</li></ul>"},{"id":"t-pexie","kind":"terminal","label":"Mucopexie / hémorroïdopexie","color":"amber","detail":"<h4>Modalité</h4><ul><li><span class=\"kw-ttt\">Ligature sous Doppler ± mucopexie</span> ou <span class=\"kw-ttt\">hémorroïdopexie</span> ; fixation mécanique ou thermique (radiofréquence, <span class=\"kw-ttt\">laser</span>)</li></ul><h4>Avantages / limite</h4><ul><li>Plus rapide, <span class=\"kw-clinique\">moins douloureuse</span>, immobilisation plus courte — mais <span class=\"kw-alerte\">risque de récidive plus important</span> qu'avec l'hémorroïdectomie</li></ul><h4>Escalade</h4><ul><li>En cas de nouvel échec → <span class=\"kw-ttt\">hémorroïdectomie</span></li></ul>"}]},"cards":[{"i":"1456bcdb242d","n":288,"o":"288-1","u":"Définition","t":"Connaître la définition des hémorroïdes","q":"Quels sont les deux groupes hémorroïdaires et leur localisation respective ?","a":"<ul><li>Le <strong>plexus interne</strong> : il est <strong>sus-pectinéal</strong> et intra-canalaire.</li><li>Le <strong>plexus externe</strong> : il est <strong>sous-pectinéal</strong> et se situe au niveau de la marge anale.</li></ul>"},{"i":"42a22efd7855","n":288,"o":"288-1","u":"Définition","t":"Connaître la définition des hémorroïdes","q":"Quelle est la composition anatomique d'une hémorroïde ?","a":"<ul><li>Des <strong>lacs veineux</strong>.</li><li>De <strong>petites artérioles sous-muqueuses</strong>.</li><li>Un <strong>réseau anastomotique intense</strong>, formant un véritable shunt artério-veineux.</li><li>Un <strong>tissu de soutien</strong> composé de fibres musculaires lisses et de tissu collagène, qui ancre la structure.</li></ul>"},{"i":"99e067b19c9e","n":288,"o":"288-1","u":"Définition","t":"Connaître la définition des hémorroïdes","q":"Quel facteur physiologique peut conduire à l'apparition d'une maladie hémorroïdaire ?","a":"<p>La <strong>laxité du matériel d'ancrage</strong> des hémorroïdes, souvent liée au vieillissement, peut entraîner une <strong>procidence ou une saillie</strong> des hémorroïdes, marquant le début de la maladie hémorroïdaire.</p>"},{"i":"bbc39df3d536","n":288,"o":"288-1","u":"Définition","t":"Connaître la définition des hémorroïdes","q":"Quelle est la définition des hémorroïdes (structures anatomiques) ?","a":"<p>Les hémorroïdes sont des <strong>structures anatomiques vasculaires</strong>, normalement présentes chez tout individu sain au niveau de l'anus. Elles sont physiologiques et ne constituent pas une maladie en soi.</p>"},{"i":"8b4d86829c03","n":288,"o":"288-10","u":"Contenu multimédia","t":"Photographies d’hémorroïdes externes et hémorroïdes internes prolabées","q":"Comment se présentent cliniquement les hémorroïdes internes prolabées ?","a":"<p>Les hémorroïdes internes prolabées sont des tuméfactions, qui peuvent être uniques ou multiples, de <strong>couleur rosée ou violacée</strong> (en cas de thrombose ou de strangulation), siégeant dans le <strong>canal anal</strong> et faisant saillie à l'extérieur de l'anus <strong>lors des efforts de poussée</strong>, voire de manière permanente selon le stade de la maladie.</p>"},{"i":"dda14617bb3b","n":288,"o":"288-10","u":"Contenu multimédia","t":"Photographies d’hémorroïdes externes et hémorroïdes internes prolabées","q":"Comment se présentent cliniquement les hémorroïdes externes à l'inspection ?","a":"<p>Les hémorroïdes externes apparaissent comme des tuméfactions bleutées, sous-cutanées, situées <strong>en périphérie de l’anus</strong>, recouvertes de peau. Elles sont visibles directement à l'inspection sans effort de poussée.</p>"},{"i":"2cda12748a91","n":288,"o":"288-11","u":"Contenu multimédia","t":"Photographies de thrombose hémorroïdaire","q":"Quelle est la caractéristique sémiologique principale d'une thrombose hémorroïdaire externe, visible à l'inspection ?","a":"<p>La thrombose hémorroïdaire externe se manifeste typiquement par une <strong>tuméfaction ferme et bleutée</strong>, localisée au niveau des <strong>plis radiés</strong> de l'anus.</p>"},{"i":"1303f0cc6359","n":288,"o":"288-13","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","q":"Quand et comment sont réalisés les traitements instrumentaux pour la pathologie hémorroïdaire interne, et quelle est leur caractéristique commune ?","a":"<p>Les traitements instrumentaux sont le traitement de fond de la maladie hémorroïdaire interne. Ils sont réalisés en consultation spécialisée, à travers un anuscope, et <strong>en dehors des poussées</strong>. Ils sont appliqués sur la muqueuse rectale au-dessus du tissu hémorroïdaire (pas sur les hémorroïdes elles-mêmes) car la muqueuse rectale est <strong>dépourvue de sensibilité thermo-algésique</strong>. Leur bénéfice est important dans plus de 3/4 des cas, mais l'efficacité est <strong>décroissante avec le suivi</strong>, nécessitant des répétitions (2 à 4 fois en moyenne, tous les mois).</p>"},{"i":"27487fc98235","n":288,"o":"288-13","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","q":"Quelle est la pierre angulaire de la prise en charge non médicamenteuse de la pathologie hémorroïdaire et quel est son objectif principal ?","a":"<p>La pierre angulaire est la lutte contre la <strong>constipation chronique</strong>. Son objectif principal est de <ul><li>limiter l'installation de la maladie</li><li>résoudre les symptômes</li><li>prévenir les récidives et les complications</li></ul> pour la pathologie hémorroïdaire.</p>"},{"i":"5be386e10f0c","n":288,"o":"288-13","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","q":"Quelles sont les options de traitement chirurgical de la pathologie hémorroïdaire et leurs principales différences ?","a":"<p>Les options de traitement chirurgical, réalisés sous anesthésie générale, péridurale ou locorégionale, sont :<ul><li>L'<strong>hémorroïdectomie</strong> (résection) : c'est le traitement de référence en termes d'efficacité, mais plus douloureux.</li><li>Les techniques de <strong>fixation / pexie</strong> (mécanique ou thermique comme la radiofréquence, le laser) : elles sont plus rapides, moins douloureuses, avec une immobilisation plus courte, mais comportent un <strong>risque de récidive plus important</strong>.</li></ul></p>"},{"i":"67e5d73d0204","n":288,"o":"288-13","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","q":"Quelles sont les principales techniques de traitement instrumental pour la pathologie hémorroïdaire et leurs particularités ?","a":"<p>Les principales techniques de traitement instrumental sont :<ul><li>La <strong>ligature élastique</strong> (technique ischémique) : considérée comme le meilleur compromis bénéfice/risque, mais <strong>contre-indiquée sous anticoagulants ou double anti-agrégation</strong>.</li><li>La <strong>sclérose</strong> (technique chimique) : injection d'un produit sclérosant 2 cm au-dessus de la ligne pectinée.</li><li>La <strong>photocoagulation infrarouge</strong> (technique thermique).</li><li>La <strong>coagulation bipolaire</strong> (technique thermique).</li><li>La <strong>cryothérapie</strong> (technique thermique).</li></ul></p>"},{"i":"9cdc972c12d6","n":288,"o":"288-13","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","q":"Comment le traitement de la pathologie hémorroïdaire est-il adapté selon le grade de Goligher ?","a":"<p>Le traitement est <strong>progressif</strong> et adapté au grade de sévérité selon l'escalade thérapeutique. On n'escalade qu'en cas d'échec du palier précédent :<ul><li><strong>Grade I</strong> : Règles Hygiéno-Diététiques (RHD) + traitement médical. Si échec : photocoagulation infrarouge ou sclérose, puis ligature.</li><li><strong>Grade II</strong> : RHD + traitement médical. Si échec : photocoagulation, sclérose ou ligature élastique, puis hémorroïdopexie / hémorroïdectomie.</li><li><strong>Grade III</strong> : RHD + traitement médical. Si échec : ligature élastique, puis mucopexie / hémorroïdopexie, voire hémorroïdectomie.</li><li><strong>Grade IV</strong> : <strong>Hémorroïdectomie d'emblée</strong> (prolapsus irréductible).</li></ul>Le principe général est de débuter par les RHD et le traitement médical, puis les procédés mini-invasifs avant d'envisager la chirurgie pour les formes sévères ou compliquées.</p>"},{"i":"f287afc987da","n":288,"o":"288-13","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","q":"Quels sont les grands principes du traitement médicamenteux des hémorroïdes et quels types de médicaments sont utilisés ?","a":"<p>Le traitement médicamenteux vise une utilisation <strong>ponctuelle</strong> lors des épisodes douloureux, en cure courte, et n'est pas le traitement des formes chroniques. Les médicaments utilisés incluent :<ul><li><strong>Antalgiques et AINS</strong> (Anti-Inflammatoires Non Stéroïdiens)</li><li><strong>Veinotoniques</strong> (ex: <strong>diosmine</strong>) dont l'efficacité est démontrée pour diminuer l'intensité et la durée des symptômes</li><li><strong>Topiques locaux</strong> (émollients, analgésiques, anti-inflammatoires, anti-œdème, favorisant la cicatrisation)</li></ul></p>"},{"i":"02d1793e38fe","n":288,"o":"288-14","u":"Prise en charge","t":"Connaître les quatre règles de préambule thérapeutique","q":"Quelle est la troisième règle de préambule thérapeutique concernant l'utilisation des traitements médicamenteux pour la pathologie hémorroïdaire ?","a":"<p>Les traitements médicamenteux sont habituellement réservés aux <strong>symptômes aigus</strong> et proposés en <strong>cure courte</strong>.</p>"},{"i":"06d247edc0cf","n":288,"o":"288-14","u":"Prise en charge","t":"Connaître les quatre règles de préambule thérapeutique","q":"Quelle est la deuxième règle de préambule thérapeutique concernant la justification du traitement de la pathologie hémorroïdaire ?","a":"<p>Dans la majorité des cas, le traitement de la pathologie hémorroïdaire est un <strong>traitement de confort</strong>.</p>"},{"i":"954d0213b3c5","n":288,"o":"288-14","u":"Prise en charge","t":"Connaître les quatre règles de préambule thérapeutique","q":"Quelle est la première règle de préambule thérapeutique concernant la prise en charge de la pathologie hémorroïdaire ?","a":"<p>Le traitement des hémorroïdes doit être réservé aux <strong>formes symptomatiques</strong>.</p>"},{"i":"9b83ca3c6137","n":288,"o":"288-14","u":"Prise en charge","t":"Connaître les quatre règles de préambule thérapeutique","q":"Quelle est la quatrième règle de préambule thérapeutique concernant le type de traitement et la prise en charge des hémorroïdes ?","a":"<p>Les procédés instrumentaux et chirurgicaux constituent le traitement de la maladie hémorroïdaire <strong>interne</strong> et relèvent d'une <strong>prise en charge spécialisée</strong>.</p>"},{"i":"2c0165ac7e22","n":288,"o":"288-15","u":"Prise en charge","t":"Connaître le traitement de la thrombose hémorroïdaire externe","q":"Quelle est la principale contre-indication au geste local (excision/incision) pour une thrombose hémorroïdaire externe ?","a":"<p>La principale contre-indication est une <strong>thrombose œdémateuse</strong>, en raison d'un risque d'inefficacité et d'hémorragie.</p>"},{"i":"734e5191f435","n":288,"o":"288-15","u":"Prise en charge","t":"Connaître le traitement de la thrombose hémorroïdaire externe","q":"Quels sont les traitements médicaux recommandés pour la thrombose hémorroïdaire externe ?","a":"<ul><li><strong>AINS</strong> (anti-inflammatoires non stéroïdiens) en première intention.</li><li><strong>Antalgiques de palier 1-2</strong>.</li><li><strong>Topiques</strong> contenant un anesthésique local.</li><li>Veinotoniques (niveau de preuve faible).</li><li><strong>Corticoïdes</strong> en cure courte : alternative si contre-indication aux AINS et au traitement chirurgical, surtout en cas de forte composante œdémateuse.</li></ul>"},{"i":"a0a2c5b9a1ea","n":288,"o":"288-15","u":"Prise en charge","t":"Connaître le traitement de la thrombose hémorroïdaire externe","q":"Quel est le principe général du traitement de la thrombose hémorroïdaire externe, en particulier pour la gestion de la douleur ?","a":"<p>Le traitement de la thrombose hémorroïdaire externe est avant tout une <strong>urgence antalgique</strong>.</p>"},{"i":"c21f006ab135","n":288,"o":"288-15","u":"Prise en charge","t":"Connaître le traitement de la thrombose hémorroïdaire externe","q":"Quel geste local peut être proposé en cas de thrombose hémorroïdaire externe, et quelles sont ses indications ?","a":"<p>Un geste local, tel que l'<strong>excision</strong> ou l'incision de la zone thrombosée, peut être réalisé en consultation. L'excision est préférable pour son efficacité et sa durabilité.</p><p>Les indications sont :</p><ul><li>D'emblée si la thrombose est vue <strong>précocement</strong>.</li><li>En cas d'<strong>inefficacité du traitement médical après 24-48 heures</strong>.</li></ul>"},{"i":"194a5e6f769f","n":288,"o":"288-4","u":"Diagnostic positif","t":"Savoir distinguer les hémorroïdes externes et internes","q":"Comment différencier la visibilité et la palpabilité des hémorroïdes externes et internes en l'absence de complication ?","a":"<p>Les hémorroïdes externes ne sont normalement <strong>pas visibles</strong> et sont <strong>non palpables</strong>, sauf en cas de thrombose. Les hémorroïdes internes ne sont visibles qu'en <strong>anuscopie</strong> (sauf prolapsus extériorisé) et sont <strong>non palpables</strong>.</p>"},{"i":"64f9d659cb32","n":288,"o":"288-4","u":"Diagnostic positif","t":"Savoir distinguer les hémorroïdes externes et internes","q":"Comment distinguer la localisation des hémorroïdes externes et internes par rapport à la ligne pectinée ?","a":"<p>Les hémorroïdes externes sont localisées en région <strong>péri-anale</strong>, immédiatement sous-cutanée, dans les plis radiés de l'anus. Les hémorroïdes internes sont <strong>intra-canalaires</strong>, en sus-pectinéal.</p>"},{"i":"c756c74a05dd","n":288,"o":"288-4","u":"Diagnostic positif","t":"Savoir distinguer les hémorroïdes externes et internes","q":"Quelles sont les complications des hémorroïdes externes et internes ?","a":"<ul><li>La seule complication des hémorroïdes externes est la <strong>thrombose hémorroïdaire externe</strong>.</li><li>Les hémorroïdes internes peuvent se compliquer d'<strong>hémorragie</strong>, de <strong>prolapsus/procidence</strong>, de <strong>crise hémorroïdaire</strong> (fluxionnaire) ou, plus rarement, de <strong>thrombose hémorroïdaire interne</strong>.</li></ul>"},{"i":"d562c35842cd","n":288,"o":"288-4","u":"Diagnostic positif","t":"Savoir distinguer les hémorroïdes externes et internes","q":"Quelles sont les différences de revêtement histologique entre les hémorroïdes externes et internes ?","a":"<p>Le plexus externe est recouvert d'un épithélium de type <strong>malpighien</strong>. Le plexus interne est recouvert d'un épithélium de type <strong>intestinal</strong>.</p>"},{"i":"000da664dfdb","n":288,"o":"288-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","q":"Quels sont les autres symptômes pouvant accompagner une thrombose hémorroïdaire externe ?","a":"<ul><li>Perception d'une <strong>boule à l'anus</strong>.</li><li><strong>Saignements tardifs et inconstants</strong>, notamment en cas de fistulisation spontanée, qui s'accompagne alors d'une diminution de la douleur.</li></ul>"},{"i":"07d72a8e9a26","n":288,"o":"288-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","q":"Quelles sont les spécificités du diagnostic de la thrombose hémorroïdaire interne, par rapport à l'externe ?","a":"<p>La thrombose hémorroïdaire interne est <strong>beaucoup plus rare</strong>. Elle se manifeste par une <strong>douleur anale aiguë perçue comme « interne »</strong>, avec une marge anale normale. Le <strong>toucher rectal est très douloureux</strong> et perçoit le thrombus alors que l'<strong>anuscopie permet de confirmer le diagnostic</strong>.</p>"},{"i":"550b85f115e8","n":288,"o":"288-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","q":"Quelle est la particularité de l'examen clinique et des examens complémentaires pour le diagnostic d'une thrombose hémorroïdaire externe ?","a":"<p>Le diagnostic est <strong>clinique</strong> et repose sur l'examen de la zone anale qui révèle une <strong>tuméfaction ferme mais non dure, bleutée et douloureuse à la palpation</strong>. Une <strong>réaction œdémateuse</strong> est souvent associée et peut masquer le thrombus. Le <strong>toucher rectal et l'anuscopie doivent être évités</strong> car très douloureux, sauf en cas de doute diagnostique. Les <strong>examens complémentaires ne sont pas nécessaires</strong>.</p>"},{"i":"8dade85109a7","n":288,"o":"288-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","q":"Quelle est la définition et la localisation typique d'une thrombose hémorroïdaire externe, la seule complication des hémorroïdes externes ?","a":"<p>La thrombose hémorroïdaire externe se manifeste par une <strong>tuméfaction ferme, bleutée et douloureuse</strong>, siégeant dans les <strong>plis radiés de l'anus</strong>. C'est la seule complication des hémorroïdes externes.</p>"},{"i":"933042dc870a","n":288,"o":"288-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","q":"Comment caractériser la douleur associée à une thrombose hémorroïdaire externe aiguë ?","a":"<p>La douleur est <strong>anale aiguë</strong>, d'installation <strong>brutale</strong> et d'<strong>intensité intense</strong>. Elle associe une sensation de <strong>cuisson, de tension et une douleur vive</strong>. Contrairement à la fissure anale, elle est <strong>peu ou pas rythmée par la défécation</strong> et contrairement aux suppurations, elle est <strong>rarement insomniante</strong>.</p>"},{"i":"99a3454ccef5","n":288,"o":"288-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","q":"Quels sont les principaux facteurs déclenchants d'une thrombose hémorroïdaire externe selon le contexte clinique ?","a":"<ul><li><strong>Exercice physique</strong>, et notamment le cyclisme.</li><li>Contrainte mécanique locale.</li><li><strong>Traumatisme</strong>, notamment l'<strong>accouchement</strong>.</li></ul>"},{"i":"6443e74b17ec","n":288,"o":"288-6","u":"Diagnostic positif","t":"Connaître les manifestations cliniques les plus fréquentes des hémorroïdes internes","q":"Décrivez les caractéristiques d'une hémorragie liée aux hémorroïdes internes.","a":"<p>L'hémorragie hémorroïdaire se manifeste par :</p><ul><li>Un horaire contemporain de la <strong>défécation</strong> ou immédiatement après.</li><li>Un sang de couleur <strong>rouge rutilant</strong> et vif (d'origine artériolaire), généralement non mélangé aux selles.</li><li>Une abondance souvent <strong>faible</strong>, se présentant comme un goutte-à-goutte (rarement giclant), souvent surestimée par les patients.</li></ul>"},{"i":"8f2142976285","n":288,"o":"288-6","u":"Diagnostic positif","t":"Connaître les manifestations cliniques les plus fréquentes des hémorroïdes internes","q":"Quelles sont les trois principales manifestations cliniques des hémorroïdes internes ?","a":"<p>Les trois principales manifestations cliniques des hémorroïdes internes sont :</p><ul><li>Les <strong>hémorragies</strong>.</li><li>Le <strong>prolapsus</strong> ou la <strong>procidence</strong>.</li><li>Les <strong>douleurs</strong> (lors d'une crise fluxionnaire).</li></ul>"},{"i":"b39de9081049","n":288,"o":"288-6","u":"Diagnostic positif","t":"Connaître les manifestations cliniques les plus fréquentes des hémorroïdes internes","q":"Quelle est la caractéristique principale du grade 2 de la classification de Goligher pour le prolapsus hémorroïdaire ?","a":"<p>Dans le grade 2 de la classification de Goligher, les hémorroïdes internes sont <strong>prolabées</strong> (visiblement en procidence dans la lumière de l'anuscope) et <strong>se réintègrent spontanément</strong> dans le canal anal.</p>"},{"i":"d3a3f52eae17","n":288,"o":"288-6","u":"Diagnostic positif","t":"Connaître les manifestations cliniques les plus fréquentes des hémorroïdes internes","q":"En ce qui concerne le prolapsus hémorroïdaire, expliquez son mécanisme et les signes associés à sa présence.","a":"<p>Le prolapsus résulte d'une <strong>laxité du tissu conjonctif sous-muqueux</strong> des hémorroïdes internes, ce qui entraîne leur extériorisation par l'orifice anal, notamment lors de la défécation, voire en permanence.</p><p>Les signes associés sont :</p><ul><li>Une <strong>gêne mécanique</strong>, décrite comme une sensation de « boule sortante » lors des efforts de poussée.</li><li>Dans les formes fréquentes ou permanentes (grades 3-4), on peut observer du <strong>prurit</strong>, un <strong>suintement</strong> et des <strong>brûlures anales</strong> (bien que le prurit ne soit pas une indication de traitement instrumental ou chirurgical des hémorroïdes).</p></ul>"},{"i":"e6b387cd6e55","n":288,"o":"288-6","u":"Diagnostic positif","t":"Connaître les manifestations cliniques les plus fréquentes des hémorroïdes internes","q":"Qu'est-ce qui caractérise le grade 4 de la classification de Goligher du prolapsus hémorroïdaire interne ?","a":"<p>Le grade 4 de la classification de Goligher correspond à des hémorroïdes internes <strong>prolabées et visibles en permanence</strong> à l'extérieur de l'anus, même sans anuscope. Elles sont <strong>non réintégrables</strong>, signant une rupture totale du ligament de Parks.</p>"}]};